// Proposal for the EXISTING Make scenario 10199316. No network or SDK imports.
// The production branch is intentionally absent: every address is a fixed QA tab.
const PROTOCOL = 'cxorbia.hr-field-transport.v1';
const SCOPE_KEYS = ['tenantId','projectId','periodId','countryCode','visitId','hrRowId','fieldKey'];
const ECHO_KEYS = ['protocolVersion',...SCOPE_KEYS,'eventId','eventDigest','bindingFingerprint','worksheetFingerprint','headerFingerprint','rowIdentityFingerprint'];
const TARGET_KEYS = [...ECHO_KEYS,'baseEventId','baseEventOrigin','baseRevision','driveId','itemId','worksheetId','rangeAddress','headerRangeAddress','rowRangeAddress','rowIdentityColumnIndexes','expectedHeaderValues','expectedRowIdentityValues','expectedBeforeValue','fieldValue'];
const QA = {
  driveId:'B2D2B478DAC4DD05', tenantId:'tya', projectId:'f3-qa-20261124', periodId:'f3-qa-20261124-2026-11',
  GT:{itemId:'B2D2B478DAC4DD05!s7752e15fa45d4038b05c88522834cb6e',name:'CXR_B14_QA_GT_20261119',cinema:'2022002',shopping:'C. Miraflores',visitId:'hr_excel_45c62e0543d229c8ca625f3cf857'},
  HN:{itemId:'B2D2B478DAC4DD05!s314e10a513f74ddd829bacab1503c0f7',name:'CXR_B14_QA_HN_20261119',cinema:'2052001',shopping:'C. Las Cascadas Honduras',visitId:'hr_excel_ec25c41b6656f0000daef0af1398'},
  fields:{escenario:{cell:'L2',index:11},tipoCombo:{cell:'K2',index:10},agendada:{cell:'S2',index:18},shopperId:{cell:'O2',index:14}}
};
function canonical(v){return Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;}
function same(a,b){return JSON.stringify(canonical(a))===JSON.stringify(canonical(b));}
function cellSame(r,a,b){
  if(r.fieldKey!=='agendada')return same(a,b);
  const day=v=>{if(v==='')return '';if(typeof v==='number'&&Number.isFinite(v)&&v>=1&&v<=100000)return new Date(Date.UTC(1899,11,30)+Math.floor(v)*86400000).toISOString().slice(0,10);return typeof v==='string'&&/^20\d\d-\d\d-\d\d$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v?v:null;};
