}
function fail(code){throw new Error('F3_QA:'+code);}
function scalar(v){return typeof v==='string'||typeof v==='boolean'||typeof v==='number'&&Number.isFinite(v);}
function parseObject(v,code){if(typeof v==='string'){try{v=JSON.parse(v);}catch{fail(code);}}if(!v||Array.isArray(v)||typeof v!=='object')fail(code);return v;}
function requestIdentity(r){return Object.fromEntries(TARGET_KEYS.map(k=>[k,['baseEventId','baseEventOrigin','baseRevision'].includes(k)?r[k]??null:r[k]]));}
function fieldScope(r){return Object.fromEntries(SCOPE_KEYS.map(k=>[k,r[k]]));}
function nowIso(input){const s=String(input.observedAt||'');if(!/^20\d\d-\d\d-\d\dT/.test(s)||!Number.isFinite(Date.parse(s)))fail('OBSERVED_TIME_REQUIRED');return new Date(s).toISOString();}
function validateRequest(input,expectedHeaders){
  const r=parseObject(input.request,'REQUEST_OBJECT'),c=QA[r.countryCode],f=QA.fields[r.fieldKey];
  if(r.protocolVersion!==PROTOCOL||!['inspect_event','write_field'].includes(r.operation)||!c||!f)fail('PROTOCOL_OR_FIELD');
  if(r.tenantId!==QA.tenantId||r.projectId!==QA.projectId||r.periodId!==QA.periodId||r.driveId!==QA.driveId||r.itemId!==c.itemId)fail('QA_SCOPE_ONLY');
  if(r.visitId!==c.visitId||r.hrRowId!==c.name+'!2')fail('ROW_SCOPE');
  if(!/^hfe-[a-f0-9]{64}$/.test(r.eventId)||!/^[a-f0-9]{64}$/.test(r.eventDigest))fail('EVENT_IDENTITY');
  for(const k of ['bindingFingerprint','worksheetFingerprint','headerFingerprint','rowIdentityFingerprint'])if(!/^[a-f0-9]{64}$/.test(r[k]))fail('FINGERPRINT');
  if(r.baseEventId!=null&&!/^hfe-[a-f0-9]{64}$/.test(r.baseEventId))fail('BASE_EVENT');
  if(![null,undefined,'hr','platform'].includes(r.baseEventOrigin))fail('BASE_ORIGIN');
  if(r.baseRevision!=null&&!/^[a-f0-9]{64}$/.test(r.baseRevision))fail('BASE_REVISION');
  if((r.baseEventId==null)!==(r.baseEventOrigin==null))fail('BASE_ORIGIN_PAIR');
  if(r.baseEventOrigin==='hr'&&!/^[a-f0-9]{64}$/.test(r.baseRevision))fail('HR_BASE_REVISION_REQUIRED');
