  if(!same(r.expectedHeaderValues,expectedHeaders)||!Array.isArray(r.expectedRowIdentityValues)||r.expectedRowIdentityValues.length!==3)fail('EXPECTED_IDENTITY_ARRAYS');
  if(!['GT','Guatemala'].includes(r.expectedRowIdentityValues[0])&&r.countryCode==='GT'||!['HN','Honduras'].includes(r.expectedRowIdentityValues[0])&&r.countryCode==='HN')fail('COUNTRY_IDENTITY');
  if(String(r.expectedRowIdentityValues[1])!==c.cinema||r.expectedRowIdentityValues[2]!==c.shopping)fail('QA_BUSINESS_IDENTITY');
  if(!scalar(r.expectedBeforeValue)||!scalar(r.fieldValue))fail('NULL_OR_NONSCALAR_FORBIDDEN');
  for(const v of [r.expectedBeforeValue,r.fieldValue])if(typeof v==='string'&&(v.length>500||/^[=+@]/.test(v)))fail('FORMULA_OR_TEXT_UNSUPPORTED');
  if(r.fieldKey==='shopperId'&&![r.expectedBeforeValue,r.fieldValue].every(v=>v===''||v==='CXOrbia QA '+r.countryCode+' F3 A'||v==='CXOrbia QA '+r.countryCode+' F3 B'))fail('SYNTHETIC_SHOPPER_LABEL_ONLY');
