  if(Number(input.worksheetStatus)!==200||ws.id!==r.worksheetId||ws.name!==c.name)fail('REMOTE_WORKSHEET_IDENTITY');
  const result={request:requestIdentity(r),operation:r.operation,eventKey:'event:'+r.eventId,
    headCanonical:JSON.stringify([r.tenantId,r.projectId,r.periodId,r.countryCode,r.visitId,r.fieldKey]),
    observedWorksheetId:ws.id,validatedAt:nowIso(input),cellIndex:f.index,
    patchUrl:'/v1.0/drives/'+encodeURIComponent(QA.driveId)+'/items/'+encodeURIComponent(c.itemId)+'/workbook/worksheets/'+encodeURIComponent(ws.id)+"/range(address='"+f.cell+"')",
    readUrl:'/v1.0/drives/'+encodeURIComponent(QA.driveId)+'/items/'+encodeURIComponent(c.itemId)+'/workbook/worksheets/'+encodeURIComponent(ws.id)+"/range(address='A1:Z2')",
    patchBody:JSON.stringify({values:[[r.fieldValue]]})};
  return {...result,observation:observation(r,input)};
}
function observation(r,input){
  let body;try{body=parseObject(input.graphBody,'GRAPH_BODY');}catch{body={};}
  const rows=body.values,shape=Number(input.graphStatus)===200&&Array.isArray(rows)&&rows.length===2&&rows.every(x=>Array.isArray(x)&&x.length===26);
  const headers=shape?rows[0]:[],row=shape?rows[1]:[],identities=shape?r.rowIdentityColumnIndexes.map(i=>row[i]):[];
  const value=shape?row[QA.fields[r.fieldKey].index]:null;
  const headerMatch=shape&&same(headers,r.expectedHeaderValues),rowMatch=shape&&same(identities,r.expectedRowIdentityValues);
  const formula=shape&&Array.isArray(body.formulas?.[1])?body.formulas[1][QA.fields[r.fieldKey].index]:null;
  const formulaSafe=shape&&Array.isArray(body.formulas?.[1])&&body.formulas[1].length===26&&(typeof formula!=='string'||!/^=/.test(formula));
  const qaOwned=shape&&rows[1][0]==='qa_f3_20261123_'+r.countryCode&&/^qa[_a-zA-Z0-9.:-]+$/.test(rows[1][2])&&/^[a-f0-9]{64}$/.test(rows[1][3]);
  const physicalMatch=shape&&headerMatch&&rowMatch&&formulaSafe&&qaOwned&&scalar(value);
  return {shape,headers,identities,value,headerMatch,rowMatch,formulaSafe,physicalMatch,
    actualHttpStatus:Number(input.graphStatus)||0,readStatus:physicalMatch?200:0,
    headerCanonical:JSON.stringify(canonical(headers)),
    rowIdentityCanonical:JSON.stringify(canonical({tenantId:r.tenantId,projectId:r.projectId,periodId:r.periodId,countryCode:r.countryCode,worksheetFingerprint:r.worksheetFingerprint,sourceRow:2,values:identities})),
    observedAt:nowIso(input)};
}
function decodeStore(exists,raw,type){
  if(typeof exists!=='boolean')fail('STORE_EXISTENCE_BOOLEAN');
  const record=parseObject(raw,'STORE_READ_OBJECT');
  if(record.schemaVersion!==1)fail('STORE_RECORD_VERSION');
  const payload=parseObject(record.payloadJson,'STORE_PAYLOAD_JSON');
  if(!exists){if(record.recordType!=='sentinel'||!same(payload,{schemaVersion:1,absent:true}))fail('STORE_SENTINEL');return null;}
  if(record.recordType!==type||payload.schemaVersion!==1)fail('STORE_RECORD_TYPE');
  return payload;
}
function receiptProven(e,r){
  return !!e&&e.schemaVersion===1&&same(e.request,requestIdentity(r))&&e.eventId===r.eventId&&e.eventDigest===r.eventDigest&&e.writeHttpStatus===200&&/^[a-f0-9]{32}$/.test(e.writeExecutionId)&&['write_ack_readback_pending','committed','conflict'].includes(e.status);
}
function headFor(event){return {schemaVersion:1,scope:event.scope,request:event.request,eventId:event.eventId,eventDigest:event.eventDigest,status:event.status,afterValue:event.afterValue,writeHttpStatus:event.writeHttpStatus,writeExecutionId:event.writeExecutionId,updatedAt:event.readbackObservedAt||event.writeObservedAt||event.intentAt};}
function outputFor(r,obs,e,head,changes={}){
  const verified=receiptProven(e,r),sameHead=!!head&&head.eventId===r.eventId&&head.eventDigest===r.eventDigest;
  const current=verified&&sameHead&&obs.readStatus===200&&cellSame(r,obs.value,e.afterValue);
  return {...Object.fromEntries(ECHO_KEYS.map(k=>[k,r[k]])),operation:r.operation,readStatus:obs.readStatus,observedValue:obs.value,
    observedHeaderValues:obs.headers,observedRowIdentityValues:obs.identities,preconditionAllowed:false,
    remoteReceiptVerified:verified,remoteWriteStatus:verified?200:0,
    remoteEventId:e?.eventId||null,remoteEventDigest:e?.eventDigest||null,currentEventId:current?r.eventId:null,
    providerExecutionId:verified?e.writeExecutionId:null,writeStatus:0,writeAttempted:false,providerWriteRequests:0,
    providerAck:current,status:verified&&current?'REPLAY_NOOP':'CONFLICT_NOOP',decision:'NO_WRITE',...changes};
}
function decide(input){
  const v=parseObject(input.validated,'VALIDATION_REQUIRED'),r={...v.request,operation:v.operation},obs=observation(r,input);
  const event=decodeStore(input.eventExists,input.eventStore,'event'),head=decodeStore(input.headExists,input.headStore,'head');
  const headKey=String(input.headHash||'');if(!/^[a-f0-9]{64}$/.test(headKey))fail('HEAD_HASH');
  const fingerprints=input.worksheetHash===r.worksheetFingerprint&&input.headerHash===r.headerFingerprint&&input.rowIdentityHash===r.rowIdentityFingerprint;
  if(!fingerprints)obs.readStatus=0;
  const reject=reason=>({action:'return',headKey,eventKey:v.eventKey,output:outputFor(r,obs,null,null,{decision:reason})});
  if(event&&!same(event.request,requestIdentity(r)))return {action:'return',headKey,eventKey:v.eventKey,output:outputFor(r,obs,null,null,{remoteEventId:event.eventId||null,remoteEventDigest:event.eventDigest||null,decision:'EVENT_SCOPE_OR_DIGEST_CONFLICT'})};
  if(head&&(!same(head.scope,fieldScope(r))||!same(Object.fromEntries(['bindingFingerprint','worksheetFingerprint','headerFingerprint','rowIdentityFingerprint','driveId','itemId','worksheetId','rangeAddress'].map(k=>[k,head.request?.[k]])),Object.fromEntries(['bindingFingerprint','worksheetFingerprint','headerFingerprint','rowIdentityFingerprint','driveId','itemId','worksheetId','rangeAddress'].map(k=>[k,r[k]])))))return reject('HEAD_SCOPE_OR_BINDING_CONFLICT');
  if(event){
    const out=outputFor(r,obs,event,head,{decision:'EXISTING_EVENT_INSPECT_ONLY'});
    if(receiptProven(event,r)&&obs.readStatus===200&&cellSame(r,obs.value,event.afterValue)&&head?.eventId===event.eventId&&head.eventDigest===event.eventDigest&&(event.status!=='committed'||head.status!=='committed')){
      const committed={...event,status:'committed',readbackObservedAt:obs.observedAt};
      return {action:'settle',headKey,eventKey:v.eventKey,eventJson:JSON.stringify(committed),headJson:JSON.stringify(headFor(committed)),output:{...out,status:'REPLAY_NOOP',providerAck:true,decision:'DURABLE_ACK_RECOVERED_NO_PATCH'}};
    }
    if(receiptProven(event,r)&&obs.readStatus===200&&!cellSame(r,obs.value,event.afterValue)&&!cellSame(r,obs.value,event.beforeValue)&&head?.eventId===event.eventId&&head.eventDigest===event.eventDigest&&head.status!=='conflict'){
      const conflict={...event,status:'conflict',readbackObservedAt:obs.observedAt};
      return {action:'settle',headKey,eventKey:v.eventKey,eventJson:JSON.stringify(conflict),headJson:JSON.stringify(headFor(conflict)),output:{...out,status:'CONFLICT_NOOP',providerAck:false,decision:'EXTERNAL_DIVERGENCE_NO_PATCH'}};
    }
    return {action:'return',headKey,eventKey:v.eventKey,output:out};
  }
  if(obs.readStatus!==200)return reject(!obs.formulaSafe?'FORMULA_CELL_NO_WRITE':'HEADER_ROW_OR_FINGERPRINT_CONFLICT');
  if(head&&!['committed','conflict'].includes(head.status))return reject('UNSETTLED_EARLIER_EVENT_NO_WRITE');
  const owner=head?.status==='committed'&&head.writeHttpStatus===200&&cellSame(r,obs.value,head.afterValue)?head.eventId:null;
  const initial=!head&&r.baseEventId==null&&r.baseEventOrigin==null;
  const causal=owner?r.baseEventOrigin==='platform'&&r.baseEventId===owner:r.baseEventOrigin==='hr'&&/^hfe-[a-f0-9]{64}$/.test(r.baseEventId)&&/^[a-f0-9]{64}$/.test(r.baseRevision)||initial;
  const allowed=causal&&cellSame(r,obs.value,r.expectedBeforeValue);
  const out=outputFor(r,obs,null,head,{preconditionAllowed:allowed,decision:allowed?'BASE_OBSERVED_NO_CAS':'BASE_CAUSAL_OR_VALUE_CONFLICT'});
  if(r.operation!=='write_field'||!allowed)return {action:'return',headKey,eventKey:v.eventKey,output:out};
  const intent={schemaVersion:1,eventId:r.eventId,eventDigest:r.eventDigest,scope:fieldScope(r),fieldKey:r.fieldKey,
    bindingFingerprint:r.bindingFingerprint,worksheetFingerprint:r.worksheetFingerprint,headerFingerprint:r.headerFingerprint,rowIdentityFingerprint:r.rowIdentityFingerprint,
    request:requestIdentity(r),beforeValue:r.expectedBeforeValue,afterValue:r.fieldValue,baseEventId:r.baseEventId??null,baseEventOrigin:r.baseEventOrigin??null,baseRevision:r.baseRevision??null,
    status:'intent',intentAt:obs.observedAt,writeHttpStatus:0,writeExecutionId:null,writeObservedAt:null,readbackObservedAt:null};
  return {action:'write',headKey,eventKey:v.eventKey,event:intent,eventJson:JSON.stringify(intent),headJson:JSON.stringify(headFor(intent)),output:out};
}
function saveAck(input){
  const plan=parseObject(input.plan,'WRITE_PLAN'),r=plan.event?.request;if(plan.action!=='write'||!r)fail('WRITE_PLAN_REQUIRED');
  const status=Number(input.patchStatus)||0,id=String(input.executionId||'');
  if(!/^[a-f0-9]{32}$/.test(id))fail('REAL_EXECUTION_ID_REQUIRED');
  const ack=status===200,event={...plan.event,status:ack?'write_ack_readback_pending':'uncertain',writeHttpStatus:status,writeExecutionId:id,writeObservedAt:nowIso(input)};
  return {event,eventKey:plan.eventKey,headKey:plan.headKey,eventJson:JSON.stringify(event),headJson:JSON.stringify(headFor(event)),writeStatus:status,writeAttempted:true};
}
function finishWrite(input){
